S = "Hakeem Force Academy"
QS = [
(S, "What is the value of log 64 divided by log 4?", ["2", "4", "3", "16"], 2, "Write 64 as 4 cubed, so log 64 = 3 log 4. Therefore log 64 / log 4 = 3.", "The change of base rule says log_b(a) = log a / log b, so this expression equals log base 4 of 64.", 2),
(S, "What is one tenth of 30?", ["3", "30", "0.3", "10"], 0, "One tenth of 30 is 30 / 10 = 3.", "Dividing by 10 moves the decimal point one place to the left.", 1),
(S, "What is one third of 120?", ["30", "36", "40", "60"], 2, "One third of 120 is 120 / 3 = 40.", "A number divisible by 3 has digits whose sum is divisible by 3; 1+2+0 = 3.", 1),
(S, "What is the value of tan 0 degrees?", ["1", "0", "Infinity", "-1"], 1, "tan 0 = sin 0 / cos 0 = 0 / 1 = 0.", "tan 90 degrees is undefined because cos 90 = 0.", 1),
(S, "What is the 2nd letter of the English alphabet?", ["A", "C", "D", "B"], 3, "The alphabet runs A, B, C, so the second letter is B.", "The English alphabet has 26 letters.", 1),
(S, "Arrange the letters of the word MANAGEMENT in alphabetical order. Which is the 3rd letter?", ["A", "E", "G", "M"], 1, "The letters in order are A, A, E, E, G, M, M, N, N, T. The third letter is E.", "MANAGEMENT has 10 letters, with A, E, M and N each repeated twice.", 2),
(S, "What is the conjugate of a real number?", ["Its negative", "Its reciprocal", "Zero", "The number itself"], 3, "The conjugate of a + bi is a - bi. For a real number b = 0, so the conjugate is the same number.", "A complex number equals its own conjugate only when it is real.", 1),
(S, "What is the common difference in the series 4, 7, 10, 13?", ["2", "3", "4", "5"], 1, "7 - 4 = 3, 10 - 7 = 3 and 13 - 10 = 3, so the difference is 3.", "Such a series is called an arithmetic progression.", 1),
(S, "What is the distance between the points (-2, 0) and (-2, -3)?", ["5", "2", "3", "1"], 2, "The x-coordinates are equal, so the distance is |0 - (-3)| = 3. By formula: sqrt(0 + 9) = 3.", "Points with the same x-coordinate lie on a vertical line.", 1),
(S, "Which is the distance formula between points (x1, y1) and (x2, y2)?", ["sqrt((x2 - x1)^2 + (y2 - y1)^2)", "(x2 - x1) + (y2 - y1)", "((x1 + x2)/2, (y1 + y2)/2)", "(y2 - y1)/(x2 - x1)"], 0, "The distance comes from the Pythagorean theorem applied to the horizontal and vertical differences.", "The formula (y2 - y1)/(x2 - x1) gives the slope, and the midpoint uses averages.", 1),
(S, "What is the HCF of 18 and 24?", ["3", "6", "9", "12"], 1, "18 = 2 x 3 x 3 and 24 = 2 x 2 x 2 x 3. The common factors are 2 and 3, so HCF = 6.", "Their LCM is 72, and HCF x LCM = 18 x 24 = 432.", 1),
(S, "What is the value of 2 + 2/3?", ["4/3", "8/3", "4", "6/3"], 1, "Division comes first: 2/3. Then 2 + 2/3 = 6/3 + 2/3 = 8/3, which is 2 and 2/3.", "In BODMAS, division is performed before addition.", 1),
(S, "Which word is a synonym of extension?", ["Reduction", "Expansion", "Shrinkage", "Closure"], 1, "Extension means an act of making something longer or larger, which is expansion.", "The antonym of extension is reduction or curtailment.", 1),
(S, "Which word is a synonym of severely?", ["Gently", "Mildly", "Harshly", "Kindly"], 2, "Severely means in a very strict or intense manner, which is harshly.", "The antonym of severely is mildly or leniently.", 1),
(S, "Where does the line y = 3 + 5y lie?", ["It is the x-axis", "It is the y-axis", "Parallel to the x-axis, so it is neither axis", "Passes through the origin"], 2, "Rearranging gives -4y = 3, so y = -3/4. This is a horizontal line parallel to the x-axis, not the axis itself.", "The x-axis is the line y = 0 and the y-axis is the line x = 0.", 1),
(S, "What comes next in the series: 1 X 2 Y Y 3 Z Z ?", ["X", "Y", "4", "Z"], 3, "The numbers 1, 2, 3 are followed by X once, Y twice and Z three times. So one more Z completes 3 ZZZ.", "The letters follow the alphabetical order X, Y, Z.", 1),
(S, "Which comes next in the series: A2, D5, F9, ?", ["G14", "H13", "G13", "I14"], 0, "Letters move +3, +2, +1 (A, D, F, G) and numbers add 3, 4, 5 (2, 5, 9, 14). So the next term is G14.", "In such series, check the letters and numbers separately.", 1),
(S, "Which is the odd one out: football, cricket, baseball, tennis?", ["Cricket", "Baseball", "Tennis", "Football"], 3, "Cricket, baseball and tennis are played by hitting the ball with a bat or racket. Football is played with the foot.", "Football is the most widely played sport in the world.", 1),
(S, "Which is the odd one out: iron, brass, tin, copper?", ["Iron", "Tin", "Brass", "Copper"], 2, "Iron, tin and copper are pure metallic elements. Brass is an alloy of copper and zinc.", "Bronze is an alloy of copper and tin.", 2),
(S, "Which letter comes immediately before W in the English alphabet?", ["U", "X", "T", "V"], 3, "The alphabet runs ... U, V, W, X, so V comes just before W.", "W is the 23rd letter of the alphabet.", 1),
(S, "Which letter comes next: A B C D E F G H ?", ["J", "K", "I", "H"], 2, "The letters are in alphabetical order, and the one after H is I.", "I is the 9th letter of the alphabet.", 1),
(S, "In the series A1, C3, D4, G?, what number follows G?", ["5", "6", "8", "7"], 3, "Each number is the alphabet position of its letter: A=1, C=3, D=4, so G=7.", "G is the 7th letter of the alphabet.", 1),
(S, "Which comes next in the series: A5, B10, C15, ?", ["D20", "D25", "E20", "D18"], 0, "Letters move forward one step (A, B, C, D) and numbers increase by 5 (5, 10, 15, 20). So the next is D20.", "The number part is the table of 5.", 1),
(S, "Which of the letters A, H, I, W, M, O, T, U, Y look the same in a mirror (vertical mirror held beside the letter)?", ["Only A, H, I and O", "Only H, I, O and W", "Only M, T, U and Y", "All of them"], 3, "Every one of these letters is symmetric about a vertical line, so each looks the same when reflected.", "Letters like B, C, D, E and K are symmetric only about a horizontal line.", 1),
]
